Author: Nick Hung <nick@andestech.com>
Date:   Sat Jun 27 22:28:53 2026 +0800

    Andes V5 CSR transport: restore + re-drain (v3 ABI)

    Behavioral. ResumeDriver restores the Andes CSR block when HYBRID_FLAG_ANDES is set (X-macro write_csr_tolerant loop + PMA, every pmaaddr before any pmacfg, mirroring the PMP ordering); StateDrain re-reads it at the exit halt so in-ROI writes reach the drained state. Bumps external/andesim_abi to the v3 commit. Unit tests cover restore, re-read, and ABI layout.

    Co-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>

diff --git a/src/hybrid/resume_driver.hpp b/src/hybrid/resume_driver.hpp
index 0df0351..5fe0444 100644
--- a/src/hybrid/resume_driver.hpp
+++ b/src/hybrid/resume_driver.hpp
@@ -240,6 +240,28 @@ public:
     write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
     write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);

+    // Andes V5 CSR block (v3): the boot-static memory-system / extension CSRs
+    // the functional engine set up before the ROI -- PMA attributes, mxstatus,
+    // ILM/DLM bases, perf throttling, stack-protection bounds, the CoDense/Zcmt
+    // table bases -- plus the DSP overflow flag (ucode). Same rationale as
+    // mcache_ctl: without them the cycle engine resumes with the wrong memory
+    // system or faults on the first CoDense/DSP op in the window. All tolerant:
+    // a core lacking a given custom CSR mirrors the write as a no-op, and a
+    // drained 0 restores the reset value. HYBRID_ANDES_CSR_LIST is the single
+    // source of truth shared with the plugin drain, StateDrain, and state_diff.
+    if (state.flags & HYBRID_FLAG_ANDES) {
+#define X(field, addr, name) write_csr_tolerant(addr, state.andes.field);
+      HYBRID_ANDES_CSR_LIST(X)
+#undef X
+      // PMA: every pmaaddr before any pmacfg (a TOR/NAPOT cfg consumes the addr
+      // already in place -- mirror the PMP ordering). On RV64 only even pmacfg
+      // CSRs exist, so slot i maps to 0xBC0 + 2*i; pmaaddr i maps to 0xBD0 + i.
+      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
+        write_csr_tolerant(HYBRID_PMA_ADDR0_CSR + i, state.andes.pmaaddr[i]);
+      for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
+        write_csr_tolerant(HYBRID_PMA_CFG0_CSR + 2 * i, state.andes.pmacfg[i]);
+    }
+
     // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
     // from QEMU1's drain value. Without this, vsim's local counter starts
     // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
diff --git a/src/hybrid/state_drain.hpp b/src/hybrid/state_drain.hpp
index 76f1f8b..c16ebd2 100644
--- a/src/hybrid/state_drain.hpp
+++ b/src/hybrid/state_drain.hpp
@@ -107,6 +107,23 @@ public:
     state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
     state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));

+    // Andes V5 CSR block (v3): re-read the transported Andes CSRs from the hart
+    // so an in-ROI write reaches the drained state instead of the stale QEMU1
+    // passthrough (same round-trip as mscratch). Tolerant reads: a CSR the core
+    // lacks mirrors as 0. HYBRID_ANDES_CSR_LIST is the single source of truth
+    // shared with the plugin drain, ResumeDriver, and state_diff.
+    if (input.flags & HYBRID_FLAG_ANDES) {
+#define X(field, addr, name) state.andes.field = read_register_64(bus_, regno_csr(addr));
+      HYBRID_ANDES_CSR_LIST(X)
+#undef X
+      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
+        state.andes.pmacfg[i] =
+          read_register_64(bus_, regno_csr(HYBRID_PMA_CFG0_CSR + 2 * i));
+      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
+        state.andes.pmaaddr[i] =
+          read_register_64(bus_, regno_csr(HYBRID_PMA_ADDR0_CSR + i));
+    }
+
     // V data regfile: dump v0..v31 to the shared scratch region via the
     // Program Buffer LAST -- after every architectural read above -- so the
     // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments

1	#pragma once
2	
3	#include "hybrid/abstract_command.hpp"
4	#include "hybrid/andes_caps.hpp"
5	#include "hybrid/dmi_poll.hpp"
6	#include "hybrid/program_buffer.hpp"
7	#include "hybrid/state_abi.h"
8	#include "hybrid/v_regfile_xfer.hpp"
9	
10	#include <array>
11	#include <cstdint>
12	#include <cstring>
13	#include <optional>
14	#include <stdexcept>
15	#include <string>
