26	
27	class ResumeDriver
28	{
29	public:
30	  // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
31	  // dmcontrol/dmstatus are run-control registers specific to this driver.
32	  static constexpr uint8_t kData0      = kDmiData0;
33	  static constexpr uint8_t kData1      = kDmiData1;
34	  static constexpr uint8_t kDmcontrol  = 0x10;
35	  static constexpr uint8_t kDmstatus   = 0x11;
36	  static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
37	  static constexpr uint8_t kCommand    = kDmiCommand;
38	
39	  static constexpr uint16_t kCsrDpc      = 0x7B1;
40	  static constexpr uint16_t kCsrDcsr     = 0x7B0;
41	  static constexpr uint16_t kCsrPmpcfg0  = 0x3A0;
42	  static constexpr uint16_t kCsrPmpaddr0 = 0x3B0;
43	  static constexpr uint16_t kCsrFcsr     = 0x003;
44	  static constexpr uint16_t kCsrMstatus  = 0x300;
45	  static constexpr uint16_t kCsrMie      = 0x304;
46	  static constexpr uint16_t kCsrMtvec    = 0x305;
47	  static constexpr uint16_t kCsrMscratch = 0x340;
48	  static constexpr uint16_t kCsrMepc     = 0x341;
49	  static constexpr uint16_t kCsrMcause   = 0x342;
50	  static constexpr uint16_t kCsrMtval    = 0x343;
51	  static constexpr uint16_t kCsrMip      = 0x344;
52	  static constexpr uint16_t kCsrMcycle   = 0xB00;
53	  static constexpr uint16_t kCsrMinstret = 0xB02;
54	  // Andes machine setup CSRs crt0 writes at boot (see hybrid_state_v1):
55	  // mcache_ctl enables the L1 I/D caches, mmisc_ctl holds misc machine config.
56	  static constexpr uint16_t kCsrMcacheCtl = 0x7CA;
57	  static constexpr uint16_t kCsrMmiscCtl  = 0x7D0;
58	  static constexpr uint16_t kCsrVstart   = 0x008;
59	  static constexpr uint16_t kCsrVxsat    = 0x009;
60	  static constexpr uint16_t kCsrVxrm     = 0x00A;
61	  static constexpr uint16_t kCsrVcsr     = 0x00F;
62	  static constexpr uint16_t kCsrVtype    = 0xC21;
63	  static constexpr uint16_t kCsrVl       = 0xC20;
64	
65	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
66	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
67	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
68	
69	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
70	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
71	
72	  static constexpr uint32_t kAbstractcsBusy        = hybrid::kAbstractcsBusy;
73	  static constexpr uint32_t kAbstractcsCmderrMask  = hybrid::kAbstractcsCmderrMask;
74	
75	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
76	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
77	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
78	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
79	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
80	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
81	
82	  static constexpr unsigned kPollIterations = kDmiPollIterations;
83	
84	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
85	  // v_scratch_gpa(ram_base, ram_size) = the mmap's top page). Defaults to the
86	  // "unset" sentinel; a non-V resume never reads it, but a V resume with the
87	  // GPA still unset throws in the sweep (no silent transport via a bogus
88	  // address). The simulator passes the real value from platform.main_memory.
89	  explicit ResumeDriver(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset)
90	      : bus_{bus}, scratch_gpa_{scratch_gpa}
91	  {}
92	
93	  void resume(const hybrid_state_v1& state)
94	  {
95	    if (state.magic != HYBRID_STATE_MAGIC)
96	      throw std::runtime_error("ResumeDriver::resume: bad magic");
97	    if (state.version != HYBRID_STATE_VERSION)
98	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
99	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
100	    if (state.priv == 2 || state.priv > 3)
101	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
102	
103	    // dmactive must transition 0->1 in its own write before any other
104	    // DMCONTROL bit is honored (RISC-V Debug Spec).
105	    bus_.write(kDmcontrol, kDmcontrolDmactive);
106	    request_halt();
107	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
108	
109	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
110	    // accepted (FS or VS == Off disables the extension and the hart NACKs
111	    // the writes). The drained state.mstatus may legitimately carry FS or
112	    // VS at Off (e.g. an OS context-switched the regs away before the
113	    // trigger fired) -- gating the write on the drained field skips the
114	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
115	    // write mstatus when either extension is in scope; force-OR Initial
116	    // when the drained field is Off. This enable is local to the vsim
117	    // phase; the state.mstatus written to the handoff file is left
118	    // unmodified.
119	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
120	      uint64_t enable_mstatus = state.mstatus;
121	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
122	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
123	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
124	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
125	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
126	    }
127	
128	    // FPR restore (requires mstatus.FS enabled above): one abstract register
129	    // write per f-reg. Abstract-only by design, like every non-V register
130	    // block -- the Program Buffer is reserved for state the abstract command
131	    // space cannot reach (the V regfile, vtype/vl).
132	    if (state.flags & HYBRID_FLAG_FP) {
133	      for (uint16_t i = 0; i < 32; ++i)
134	        write_64bit_register(regno_fpr(i), state.fpr[i]);
135	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
136	      // fallback scratch x5 is overwritten by the GPR loop below.
137	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
138	    }
139	
140	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
141	    // the GPR loop overwrites x5 afterward so state is preserved).
142	    if (state.flags & HYBRID_FLAG_V) {
143	      // V data regfile: reload v0..v31 from the shared scratch region via the
144	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
145	      // because the sweep's own vsetvl (e8/m8) clobbers vtype/vl/vstart, which
146	      // the restore then overwrites with the architectural values. The sweep
147	      // uses x5/x6/x7 as scratch (x7 is the group base pointer); the GPR loop
148	      // below restores all three. The scratch is vlenb-packed
149	      // (stage_v_to_scratch), so the sweep takes only the runtime vlenb.
150	      if (scratch_gpa_ == kVScratchGpaUnset)
151	        throw std::runtime_error(
152	          "ResumeDriver::resume: V state present but scratch GPA unset");
153	      pb_v_data_sweep(bus_, scratch_gpa_, state.vlenb, /*load=*/true);
154	
155	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
156	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
157	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
158	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
159	      write_64bit_register(regno_gpr(5), state.vl);
160	      write_64bit_register(regno_gpr(6), state.vtype);
161	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
162	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
163	
164	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
165	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
166	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
167	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
168	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
169	    }
170	
171	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
172	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
173	    // in the drained privilege; M-mode states skip the write (prv already 3).
174	    // Before the GPR loop: a PB fallback would clobber scratch x5.
175	    if (state.priv != 3) {
176	      // L2 slice: with PMP implemented and no matching entry, every S/U
177	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
178	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
179	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
180	      // RV64. Tolerant writes: entries beyond what the hart implements
181	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
182	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
183	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
184	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
185	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
186	
187	      const uint64_t dcsr =
188	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
189	      write_csr_abstract_or_pb(kCsrDcsr,
190	                               (dcsr & ~uint64_t{0x3}) | state.priv);
191	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
192	      // silently measure the ROI in the wrong privilege. Verify and abort.
193	      const uint64_t got =
194	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
195	        & 0x3u;
196	      if (got != state.priv)
197	        throw std::runtime_error(
198	          "ResumeDriver::resume: engine does not implement privilege level "
199	          + std::to_string(state.priv)
200	          + " (dcsr.prv pinned to " + std::to_string(got)
201	          + "); pick an S/U-capable engine");
202	    }
203	
204	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite): one
205	    // abstract register write per GPR.
206	    for (uint16_t i = 1; i < 32; ++i)
207	      write_64bit_register(regno_gpr(i), state.gpr[i]);
208	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
209	
210	    write_csr_tolerant(kCsrMtvec, state.mtvec);
211	
212	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
213	    // register with no hardware side effects, legal to use inside a trap-free
214	    // ROI. Restore it so a value stashed before the handoff survives into the
215	    // vsim phase.
216	    write_csr_tolerant(kCsrMscratch, state.mscratch);
217	
218	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
219	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
220	    // value stashed before the handoff must survive into the vsim phase (same
221	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
222	    // hardware-driven pending bits, or mtval on a core that hardwires it)
223	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
224	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
225	    write_csr_tolerant(kCsrMepc,   state.mepc);
226	    write_csr_tolerant(kCsrMcause, state.mcause);
227	    write_csr_tolerant(kCsrMtval,  state.mtval);
228	    write_csr_tolerant(kCsrMie,    state.mie);
229	    write_csr_tolerant(kCsrMip,    state.mip);
230	
231	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
232	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
233	    // caches) but has no cache model, so without this the cycle engine resumes
234	    // at the ROI with caches at their reset default -- DISABLED -- and the
235	    // whole measured window runs uncached, inflating it severalfold. Tolerant
236	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
237	    // write as a no-op, and a drained 0 (caches were off) restores the reset
238	    // state, so this is always safe to issue.
239	    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
240	    write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);
241	
242	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
243	    // from QEMU1's drain value. Without this, vsim's local counter starts
244	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
245	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
246	    // overwrite here as the GPR loop already ran.
247	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
248	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
249	
250	    clear_cmderr_if_set();
251	    request_resume();
252	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
253	                   "ResumeDriver resume");
254	  }
255	
256	private:
257	  void request_halt()
258	  {
259	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
260	  }
261	
262	  void request_resume()
263	  {
264	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
265	  }
266	
267	  void write_64bit_register(uint16_t regno, uint64_t value)
268	  {
269	    write_register_abstract(bus_, regno, value);
270	  }
271	
272	  // Abstract-first CSR write with Program Buffer fallback.
273	  // Tries an abstract register write; if the DM signals cmderr, clears it,
274	  // stages the value in scratch_gpr via abstract GPR write, then executes a
275	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
276	  // to x5 (t0) which the GPR restore loop overwrites later.
277	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
278	                                 uint8_t scratch_gpr = 5)
279	  {
280	    write_64bit_register(regno_csr(csr), value);
281	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
282	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
283	    write_64bit_register(regno_gpr(scratch_gpr), value);
284	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
285	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
286	  }
287	
288	  // Write a CSR-addressable register and clear any cmderr the DM raised.
289	  // Used for CSRs whose abstract-access support may be implementation
290	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
291	  // remaining writes.
292	  void write_csr_tolerant(uint16_t csr, uint64_t value)
293	  {
294	    write_64bit_register(regno_csr(csr), value);
295	    clear_cmderr_if_set();
296	  }
297	
298	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
299	  // is rejected until the bits are W1C-cleared. We tolerate per-register
300	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
301	  // error before resuming so the hart isn't left in a stuck state.
302	  // B17: record the last observed non-zero cmderr and a clear count so a
303	  // partially-broken restore is observable via the public accessors
304	  // instead of silently swallowed.
305	  void clear_cmderr_if_set()
306	  {
307	    const auto status = bus_.read(kAbstractcs);
308	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
309	    if (code != 0u) {
310	      last_observed_cmderr_ = code;
311	      ++cmderr_clear_count_;
312	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
313	    }
314	  }
315	
316	  DmiBus& bus_;
317	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
318	  uint32_t last_observed_cmderr_ = 0;
319	  uint64_t cmderr_clear_count_   = 0;
320	
321	public:
322	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
323	  // at least one abstract write tripped a sticky cmderr the restore
324	  // tolerated by clearing. cmderr_clear_count() is the total number of
325	  // such clears across all calls into clear_cmderr_if_set() this run.
326	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
327	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
328	};
329	
330	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
331	// via an Abstract Command. Halts-and-reads contract: caller must have the
332	// hart in the halted state. Shared by StateDrain (drain at exit). If
333	// abstractcs.cmderr goes sticky after the command, the helper clears it and
334	// reports 0 rather than blocking the caller -- a missing CSR mirrors as zero
335	// instead of corrupting the adjacent field.
336	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
337	                                     const char* poll_label
338	                                       = "read_register_64")
339	  -> std::optional<uint64_t>
340	{
341	  using RD = ResumeDriver;
342	  bus.write(RD::kCommand,
343	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
344	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
345	  const auto status = bus.read(RD::kAbstractcs);
346	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
347	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
348	    return std::nullopt;
349	  }
350	  const uint64_t lo = bus.read(RD::kData0);
351	  const uint64_t hi = bus.read(RD::kData1);
352	  return lo | (hi << 32);
353	}
354	
355	inline auto read_register_64(DmiBus& bus, uint16_t regno,
356	                             const char* poll_label = "read_register_64")
357	  -> uint64_t
358	{
359	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
360	}
