1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/dmi_poll.hpp"
9	#include "hybrid/resume_driver.hpp"
10	#include "hybrid/state_abi.h"
11	#include "hybrid/v_regfile_xfer.hpp"
12	
13	#include <cstdint>
14	
15	namespace hybrid
16	{
17	
18	class StateDrain
19	{
20	public:
21	  using RD = ResumeDriver;
22	
23	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
24	  // the mmap's top page, v_scratch_gpa(ram_base, ram_size)). Defaults to the
25	  // unset sentinel; only the V dump sweep consults it, and it throws there if
26	  // a V drain is reached with the GPA unset (no silent dump to a bogus
27	  // address). The simulator passes the real value from platform.main_memory.
28	  explicit StateDrain(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset)
29	      : bus_{bus}, scratch_gpa_{scratch_gpa}
30	  {}
31	
32	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
33	  // drain_with_passthrough when the QEMU 1 snapshot is available.
34	  auto drain() -> hybrid_state_v1
35	  {
36	    hybrid_state_v1 state{};
37	    state.magic   = HYBRID_STATE_MAGIC;
38	    state.version = HYBRID_STATE_VERSION;
39	    state.flags   = HYBRID_FLAG_RV64;
40	    halt_and_capture_pc_priv(state);
41	
42	    for (uint16_t i = 1; i < 32; ++i)
43	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
44	
45	    return state;
46	  }
47	
48	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
49	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
50	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
51	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set, also
52	  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
53	  // and vreg remain pass-through (read-only / too large for DM).
54	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
55	  // contribution would otherwise be discarded as the passthrough preserves
56	  // QEMU1's pre-handoff value.
57	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
58	  {
59	    auto state = input;
60	    halt_and_capture_pc_priv(state);  // L6: pc + privilege at the exit halt
61	
62	    // GPRs/FPRs: one abstract register read each. Abstract-only by design,
63	    // like the resume side -- the Program Buffer is reserved for state the
64	    // abstract command space cannot reach (the V regfile, vtype/vl).
65	    for (uint16_t i = 1; i < 32; ++i)
66	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
67	
68	    if (input.flags & HYBRID_FLAG_FP) {
69	      for (uint16_t i = 0; i < 32; ++i)
70	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
71	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
72	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
73	    }
74	
75	    if (input.flags & HYBRID_FLAG_V) {
76	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
77	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
78	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
79	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
80	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
81	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
82	    }
83	
84	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
85	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
86	    // dropped and the stale QEMU1 value passes through into the drained state.
87	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
88	
89	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
90	    // restores them), so re-read them -- an in-ROI write must reach the drained
91	    // state instead of the stale QEMU1 passthrough value.
92	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
93	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
94	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
95	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
96	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
97	
98	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
99	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
100	
101	    // V data regfile: dump v0..v31 to the shared scratch region via the
102	    // Program Buffer LAST -- after every architectural read above -- so the
103	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
104	    // cannot corrupt the values already captured. The simulator's
105	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
106	    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
107	    if (input.flags & HYBRID_FLAG_V)
108	      dump_v_to_scratch(input.vlenb);
109	
110	    return state;
111	  }
112	
113	private:
114	  // Halt the hart and capture the two control fields every drain path needs:
115	  // privilege (dcsr.prv, L6) and PC (dpc). Header fields and the register
116	  // blocks are filled by the caller, so drain() and drain_with_passthrough
117	  // share one halt + prologue. dmactive must transition 0->1 in its own write
118	  // before haltreq is honored (RISC-V Debug Spec), then wait for allhalted.
119	  void halt_and_capture_pc_priv(hybrid_state_v1& state)
120	  {
121	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
122	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
123	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
124	                   "StateDrain halt");
125	
126	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
127	                                  "StateDrain DCSR") & 0x3u;
128	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
129	  }
130	
131	  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
132	  // L26: guards on the configured scratch GPA so a V drain never stores to a
133	  // bogus address (mirror of ResumeDriver's reload-sweep guard).
134	  void dump_v_to_scratch(uint64_t vlenb)
135	  {
136	    if (scratch_gpa_ == kVScratchGpaUnset)
137	      throw std::runtime_error(
138	        "StateDrain: V state present but scratch GPA unset");
139	    pb_v_data_sweep(bus_, scratch_gpa_, vlenb, /*load=*/false);
140	  }
141	
142	  DmiBus& bus_;
143	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
144	};
145	
146	}  // namespace hybrid
