111	    // restores them), so re-read them -- an in-ROI write must reach the drained
112	    // state instead of the stale QEMU1 passthrough value.
113	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
114	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
115	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
116	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
117	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
118	
119	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
120	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
121	
122	    // Andes V5 + M-ext CSR block (v3/v4): re-read the transported CSRs so an
123	    // in-ROI write reaches the drained state instead of the stale QEMU1
124	    // passthrough (same round-trip as mscratch). One caps-gated abstract read
125	    // per CSR. See drain_andes_m_ext.
126	    drain_andes_m_ext(state);
127	
128	    // v5: re-read the writable L2C config registers (the ones ResumeDriver
129	    // restored) so the --verify oracle sees the round-tripped values instead of
130	    // the stale QEMU1 passthrough. The ROI is trap-free and does not touch L2C
131	    // config, so these must match the producer. Clobbers x5/x6 -- safe here, the
132	    // GPRs are already captured above and the hart is terminal. See drain_l2c.
133	    drain_l2c(state);
134	
135	    // V data regfile: dump v0..v31 to the shared scratch region via the
136	    // Program Buffer LAST -- after every architectural read above -- so the
137	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
138	    // cannot corrupt the values already captured. The simulator's
139	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
140	    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
141	    if (input.flags & HYBRID_FLAG_V)
142	      dump_v_to_scratch(input.vlenb);
143	
144	    return state;
145	  }
146	
147	  // #1 (drain-minimal): refresh only mcycle/minstret from the hart and pass
148	  // every other field through from the QEMU1 snapshot. Used when --verify is
149	  // off: the driver then consumes only the vsim mcycle delta, so the full
150	  // register-file readback drain_with_passthrough performs (~190 DMI abstract
151	  // commands -- f0..f31, the V dump sweep, the Andes/M-ext blocks, ...) is pure
152	  // wasted wall-clock. The hart is left halted, identical to the full drain, so
153	  // the caller's file-write + exit path is unchanged.
154	  auto drain_counters_only(const hybrid_state_v1& input) -> hybrid_state_v1
155	  {
156	    halt("StateDrain halt (minimal)");
157	
158	    auto state     = input;
159	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle),
160	                                      "StateDrain mcycle");
161	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret),
162	                                      "StateDrain minstret");
163	    return state;
164	  }
165	
166	private:
167	  // Debug-Module halt-and-wait, shared by drain() and drain_counters_only():
168	  // dmactive must transition 0->1 in its own write before haltreq is honored
169	  // (RISC-V Debug Spec), then wait for allhalted. `ctx` labels the poll.
170	  void halt(const char* ctx)
171	  {
172	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
173	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
174	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted, ctx);
175	  }
176	
177	  // Halt the hart and capture the two control fields every drain path needs:
178	  // privilege (dcsr.prv, L6) and PC (dpc). Header fields and the register
179	  // blocks are filled by the caller, so drain() and drain_with_passthrough
180	  // share one halt + prologue.
181	  void halt_and_capture_pc_priv(hybrid_state_v1& state)
182	  {
183	    halt("StateDrain halt");
184	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
185	                                  "StateDrain DCSR") & 0x3u;
186	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
187	  }
188	
189	  // Andes V5 + M-ext CSR drain: one caps-gated abstract read per CSR into
190	  // state. Abstract-only by design, same caps gate + canonical order as the
191	  // ResumeDriver restore.
192	  void drain_andes_m_ext(hybrid_state_v1& state)
193	  {
194	    const bool andes = state.flags & HYBRID_FLAG_ANDES;
195	    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
196	    if (!andes && !mext) return;
197	
198	    if (andes) {
199	#define X(field, addr, name) \
200	  if (caps_.supports_csr(addr)) \
201	    state.andes.field = read_register_64(bus_, regno_csr(addr));
202	      HYBRID_ANDES_CSR_LIST(X)
203	#undef X
204	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
205	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
206	          state.andes.pmacfg[i] =
207	            read_register_64(bus_, regno_csr(HYBRID_PMA_CFG0_CSR + 2 * i));
208	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
209	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
210	          state.andes.pmaaddr[i] =
211	            read_register_64(bus_, regno_csr(HYBRID_PMA_ADDR0_CSR + i));
212	    }
213	    if (mext) {
214	#define X(field, addr, name) \
215	  if (caps_.supports_csr(addr)) \
216	    state.m_ext.field = read_register_64(bus_, regno_csr(addr));
217	      HYBRID_M_EXT_CSR_LIST(X)
218	#undef X
219	    }
220	  }
221	
222	  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
223	  // L26: guards on the configured scratch GPA so a V drain never stores to a
224	  // bogus address (mirror of ResumeDriver's reload-sweep guard).
225	  void dump_v_to_scratch(uint64_t vlenb)
226	  {
227	    if (scratch_gpa_ == kVScratchGpaUnset)
228	      throw std::runtime_error(
229	        "StateDrain: V state present but scratch GPA unset");
230	    pb_v_data_sweep(bus_, scratch_gpa_, vlenb, /*load=*/false);
231	  }
232	
233	  // v5: re-read the writable L2C config registers via Program-Buffer word loads,
234	  // the dual of ResumeDriver::restore_l2c. Reads back ONLY the registers the
235	  // resume side restored -- Control, HPM Control, Way Allocation Masks -- so the
236	  // --verify oracle compares round-tripped values. Hard-gated on the engine
237	  // having an L2C (a load from an absent region faults the Program Buffer).
238	  void drain_l2c(hybrid_state_v1& state)
239	  {
240	    if (!(state.flags & HYBRID_FLAG_L2C)) return;
241	    if (!l2c_present_) return;
242	
243	    state.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8]  = pb_load_l2c_reg(HYBRID_L2C_OFF_CONTROL);
244	    state.l2c.reg[HYBRID_L2C_OFF_HPM_CTL0 / 8] = pb_load_l2c_reg(HYBRID_L2C_OFF_HPM_CTL0);
245	    for (uint32_t i = 0; i < HYBRID_L2C_WAYMASK_NUM; ++i) {
246	      const uint32_t off = HYBRID_L2C_OFF_WAYMASK0 + i * 8u;
247	      state.l2c.reg[off / 8] = pb_load_l2c_reg(off);
248	    }
249	  }
250	
251	  // One L2C register read-back: stage the MMIO address in x6, execute
252	  // `lwu x5, 0(x6)` in the Program Buffer, then read x5. lwu (zero-extend) so a
253	  // 32-bit register value does not sign-pollute the drained u64. Word access
254	  // per DS220 11.8.3 (< 8 bytes).
255	  auto pb_load_l2c_reg(uint32_t offset) -> uint64_t
256	  {
257	    write_register_abstract(bus_, regno_gpr(6), l2c_base_ + offset);
258	    const std::array<uint32_t, 1> pb = { encode_lwu(5, 6, 0) };
259	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
260	    return read_register_64(bus_, regno_gpr(5), "StateDrain L2C reg");
261	  }
262	
263	  DmiBus& bus_;
264	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
265	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
266	  bool l2c_present_     = false;              // v5: engine has an L2C (set_l2c)
267	  uint64_t l2c_base_    = 0;                  // v5: L2C MMIO register base
268	};
269	
270	}  // namespace hybrid
